package com.bankpp.formulario;
import com.bankpp.model.*;import com.bankpp.repository.impl.*;import com.bankpp.service.*;import javax.swing.*;import java.awt.BorderLayout;import java.awt.GridLayout;import java.math.BigDecimal;
public final class OperacionesForm extends JPanel {
    private JPanel panelPrincipal; private JComboBox<CuentaBancaria> cmbCuentaOrigen; private JTextField txtCuentaDestino, txtMonto; private JButton btnRetirar, btnTransferir; private JLabel lblEstado;
    private final Usuario usuario; private final CuentaService cuentas = new CuentaService(new CuentaRepositoryJdbc()); private final TransaccionService transacciones = new TransaccionService(new TransaccionRepositoryJdbc());
    public OperacionesForm(Usuario usuario) { this.usuario = usuario; if (panelPrincipal == null || cmbCuentaOrigen == null || txtCuentaDestino == null || txtMonto == null || btnRetirar == null || btnTransferir == null || lblEstado == null) crearInterfaz(); setLayout(new BorderLayout()); add(panelPrincipal, BorderLayout.CENTER); cargarCuentas(); btnRetirar.addActionListener(e -> retirar()); btnTransferir.addActionListener(e -> transferir()); }
    private void crearInterfaz() { panelPrincipal = new JPanel(new GridLayout(0, 2, 8, 8)); panelPrincipal.setBorder(BorderFactory.createEmptyBorder(16,16,16,16)); cmbCuentaOrigen = new JComboBox<>(); txtCuentaDestino = new JTextField(); txtMonto = new JTextField(); btnRetirar = new JButton("Retirar"); btnTransferir = new JButton("Transferir"); lblEstado = new JLabel(" "); panelPrincipal.add(new JLabel("Estado:")); panelPrincipal.add(lblEstado); panelPrincipal.add(new JLabel("Cuenta origen:")); panelPrincipal.add(cmbCuentaOrigen); panelPrincipal.add(new JLabel("Cuenta destino (transferencia):")); panelPrincipal.add(txtCuentaDestino); panelPrincipal.add(new JLabel("Monto:")); panelPrincipal.add(txtMonto); panelPrincipal.add(btnRetirar); panelPrincipal.add(btnTransferir); }
    private void cargarCuentas() { try { for (CuentaBancaria c : cuentas.listarCuentas(usuario.getId())) cmbCuentaOrigen.addItem(c); boolean tieneCuenta = cmbCuentaOrigen.getItemCount() > 0; lblEstado.setText(tieneCuenta ? "Selecciona una cuenta para operar." : "No hay cuenta aprobada. Solicita la apertura y espera la aprobación."); btnRetirar.setEnabled(tieneCuenta); btnTransferir.setEnabled(tieneCuenta); } catch (RuntimeException e) { lblEstado.setText("No se pudieron cargar las cuentas."); btnRetirar.setEnabled(false); btnTransferir.setEnabled(false); } }
    private void retirar() { try { CuentaBancaria c = (CuentaBancaria) cmbCuentaOrigen.getSelectedItem(); if (c == null) throw new IllegalArgumentException("No hay una cuenta de origen"); transacciones.retirar(c.getId(), usuario.getId(), new BigDecimal(txtMonto.getText().trim())); JOptionPane.showMessageDialog(this, "Retiro guardado."); } catch (RuntimeException e) { error(e); } }
    private void transferir() { try { CuentaBancaria origen = (CuentaBancaria) cmbCuentaOrigen.getSelectedItem(); if (origen == null) throw new IllegalArgumentException("No hay una cuenta de origen"); CuentaBancaria destino = cuentas.buscarPorNumero(txtCuentaDestino.getText().trim()).orElseThrow(() -> new IllegalArgumentException("No existe la cuenta destino")); transacciones.transferir(origen.getId(), destino.getId(), usuario.getId(), new BigDecimal(txtMonto.getText().trim())); JOptionPane.showMessageDialog(this, "Transferencia guardada."); } catch (RuntimeException e) { error(e); } }
    private void error(Exception e) { JOptionPane.showMessageDialog(this, e.getMessage(), "Operación", JOptionPane.ERROR_MESSAGE); }
}
